import java.util.*;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int n : nums) sum += n;
        if (sum % k != 0) return false;
        int target = sum / k;
        Arrays.sort(nums);
        if (nums[nums.length - 1] > target) return false;
        boolean[] used = new boolean[nums.length];
        return backtrack(nums, used, k, 0, 0, target);
    }

    private boolean backtrack(int[] nums, boolean[] used, int k, int start, int curSum, int target) {
        if (k == 0) return true;
        if (curSum == target) return backtrack(nums, used, k - 1, 0, 0, target);
        for (int i = start; i < nums.length; i++) {
            if (used[i] || curSum + nums[i] > target) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            if (backtrack(nums, used, k, i + 1, curSum + nums[i], target)) return true;
            used[i] = false;
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int n : nums) sum += n;
        if (sum % k != 0) return false;
        int target = sum / k;
        for (int n : nums) if (n > target) return false;
        int total = 1 << nums.length;
        int[] dp = new int[total];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] == -1) continue;
            for (int i = 0; i < nums.length; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nextMask = mask | (1 << i);
                if (dp[nextMask] != -1) continue;
                int newSum = dp[mask] + nums[i];
                if (newSum <= target) {
                    dp[nextMask] = newSum % target;
                }
            }
        }
        return dp[total - 1] == 0;
    }
}
